NIGHT_LOADED({"seed":1090,"generated_at":"2026-10-21T06:00:00Z","chain":[1,2,4,3,5],"frame":{"collector":"J.D.","intro":["Je bent de nieuwe assistent.","Op tafel ligt een briefje van de verzamelaar.","De sleutel van de voordeur zit in zijn jas, en hij is naar huis.","De klok zegt kwart over negen.","Je begint te ordenen."],"note_table":"Twaalf enveloppen invoegen.\nKast vijf blijft dicht.\nSluit af vóór twaalven.\n— J.D.","note_final":"Goed opgeborgen. Morgen om negen. — J.D.","card_desk":{"kind":"Sage","description":"In het Centraal Sagenarchief staat een leestafel met een groen kleed, en daarop een lamp met een groene kap. Langs de muur staan vijf kasten met laden vol kaarten. 's Avonds, als de anderen weg zijn, zit daar de assistent die 's avonds doorwerkte, en leest. Men ziet alleen de handen in het lamplicht.","place":"Amsterdam","prov":"N.-H.","year":1936,"code":null,"initials":"J.D.","teller":"de vorige assistent","note":"Niet lezen. Opbergen."},"trail_notes":["Niet door mij opgetekend. Mijn vorige assistent.","Zelfde hand. Hij werkte 's avonds door.","Zijn laatste. Daarna geen kaarten meer van hem.","Deze heeft hij niet opgeborgen. Ik ook niet."],"card_five":{"kind":"Sage","description":"Er was eens een nieuwe assistent op het Sagenarchief die 's avonds bleef om het opbergen af te maken. De verzamelaar was naar huis gegaan. De assistent zette vier kasten op orde en maakte toen ook de vijfde open, al was gezegd dat die dicht moest blijven. Daarna is de assistent niet meer gezien. De kaarten lagen keurig op volgorde, en wat de assistent daar zag, dat was ____.","place":"Amsterdam","prov":"N.-H.","year":"tomorrow","teller":"J.D.","initials":"J.D.","code":null},"final_words":["niets","mij","mijzelf","de assistent","de vorige assistent"],"door_locked":"Op slot. De sleutel zit in de jas van J.D.","midnight":"De klok slaat twaalf.","good_end":"Goed gedaan. Kast vijf blijft dicht.","nee":"Nee.","not_yet":"Nog niet.","into_envelope":"In de envelop.","archive_note":"Achter het schot hoef je vannacht niet.","finish_first":"Nog niet. Eerst kast {roman}.","digit_note":"{n}. Het cijfer van kast {roman}.","digit_first":"Onthouden: het slot van kast V wil er vier.","found_notes":{"chair":"Eén ligt waar ik hem gisteren neerlegde.","lamp":"Eén ligt onder de lamp. Niet de lamp verzetten.","coat":"Eén zit in mijn jas. Jas laten hangen.","typewriter":"Eén zit nog in de machine."},"floor_note":"Die hoort niet in die la.","machine_continued":"— vervolg in la 3 —","reactions":{"reopen_filed":"Die was klaar.","stalled":"Opschieten.","read_desk":"Ik had gezegd: niet lezen.","typo3":"Het staat er. Lees.","other_hand":"hij komt niet terug","five_shut":"Dicht."},"citation":"Bron: Nederlandse Volksverhalenbank, Meertens Instituut (KNAW), www.verhalenbank.nl"},"cabinets":[{"id":1,"label":"Voortekenen","digit":4,"drawers":[{"id":"1-1","type":"P2","difficulty":3.0002,"rank":0.0882,"note":"Zonder plaats. Ergens tussen de andere drie. Prik hem op de kaart.","cards":[{"id":"c1","story_id":"WEV000602","role":"target","render":{"description":"Man ziet huis in brand staan, en voelt dat de muren warm zijn, een voorteken dat het huis zal afbranden.","place":null,"prov":"Gr.","year":1962,"code":"SINSAG 0491","initials":"F.W.","url":"https://www.verhalenbank.nl/items/show/42965","original":"2 Voorloop.\nOp een morgen ging ik naar het werk. \nDaar zag ik opeens het huis van Timp in brand staan.\nNu moet men daar zo snel mogelijk heen gaan.\nZijn de muren koud, dan komt er een dode in dat huis, zijn de muren warm, dan brandt het op.\nIk voelde dus, de muren waren warm.\nDadelijk ging ik naor de vrouw terug.\nIk zeg: \"Timp zien hoes brandt gauw op.\"\nHet heeft nog twee jaar geduurd, toen ging het.","lang":"Standaardnederlands; Gronings","front":"original"},"home":"1-1"},{"id":"c2","story_id":"WEV005903","role":"helper","render":{"description":"Bij afbranden van zijn boerderij vertelt man dat hij lang van tevoren heeft gezien dat het huis in brand staat, maar er over heeft gezwegen.","place":"Wessingtange","prov":"Gr.","year":1963,"code":"SINSAG 0491","initials":"F.W.","url":"https://www.verhalenbank.nl/items/show/43264","original":"Veurloop.\nJoarn leden is hier brand west. Ik huilp de boer mit alles. De man stön aal man stil te kiekn en zee:“Nôn brand e ja.”\nIk vruig:“Hou komst door bie, wat betaikent dat?”\n“t Is wol al tien joar leden”, zee e dou, “op n oavend kwam k bie hoes en dou stôn alles in lichtelaaie. k Heb dr nooit over proot, mit ganaine, man nôn brand e ja.”","lang":"Gronings","front":"original"},"home":"1-1","geo":[52.9175,7.14444]},{"id":"c3","story_id":"WEV007406","role":"helper","render":{"description":"Lichten worden gezien als voorloop van brand.","place":"Musselkanaal","prov":"Gr.","year":1963,"code":"SINSAG 0491","initials":"F.W.","url":"https://www.verhalenbank.nl/items/show/44126","original":"Lichten zaggen ze vrouger voak. \"dr brandt weer wat\", zeden ze, zel wel weer gauw n huus aan goan. Dat geleuf was algemain.","lang":"Gronings","front":"original"},"home":"1-1","geo":[52.9325,7.01528]},{"id":"c4","story_id":"WEV013008","role":"helper","render":{"description":"Voorspelling dat alle witte huizen afbranden komt uit, alleen witte kerk staat er nog.","place":"Bourtange","prov":"Gr.","year":1966,"code":"SINSAG 0491","initials":"F.W.","url":"https://www.verhalenbank.nl/items/show/44092","original":"Oal vrouw K. zag vrouger ale widde huuzn in Boertange brannen.\n“Zai brant aal op”, zee ze. En t oal hef nog gliek kreegn ook. Allaind de widde kerke stait dr nog.","lang":"Gronings","front":"original"},"home":"1-1","geo":[53.01,7.19028]}],"hints":["Drie plaatsen staan er al. De vierde ligt daartussen.","Binnen 2 uur lopen van Wessingtange.","Zoek Jipsingboertange op de kaart."],"lock":{"kind":"place","target_geo":[52.965,7.10139],"radius_km":6.0},"on_success":{"fill_field":{"card":"c1","field":"place","value":"Jipsingboertange"},"stack":["c1","c2","c3","c4"]},"found_card":null},{"id":"1-2","type":"P3","difficulty":1.1936,"rank":0.3801,"note":"Eén hoort hier niet. Terug naar zijn eigen kast.","cards":[{"id":"c1","story_id":"CJ053808","role":"member","render":{"description":"Als eksters in de tuin bij het huis schetteren, is er een sterfgeval op komst. Het is een voorteken.","place":"Houtigehage","prov":"Fr.","year":1968,"code":"SINSAG 0486","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/25423","original":"As eksters op 'e tún by hûs skatterje, dan komt der in sterfgefal.","lang":"Fries (Woudfries)","front":"original"},"home":"1-2"},{"id":"c2","story_id":"CJ064413","role":"member","render":{"description":"Schetterende eksters rond het huis betekent dat er gauw een sterfgeval in dat huis komt.","place":"Boelenslaan","prov":"Fr.","year":1969,"code":"SINSAG 0486","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/27273","original":"As der eksters om 't hûs hinne skatteren, dat bitsjutte ek, dat der yn dat hûs mei gauwens ien stjerre soe.","lang":"Fries (Woudfries)","front":"original"},"home":"1-2"},{"id":"c3","story_id":"CJ035001","role":"intruder","render":{"description":"Op een spookplaats werd vroeger vaak een witte dame op een paard gesignaleerd. Het is een spookvrouw.","place":"Harkema","prov":"Fr.","year":1968,"code":"SINSAG 0310","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/22709","original":"Op 'e Lytse Wei by de Harkema ried froeger in wite dame op in hynder, doe wie de Lytse Wei noch in sânpaed.\nDurk Pitstra hat har us njonken him hawn op in joun, doe siet er op syn eigen hynder om dat yn 't lân to bringen. Hwat hurder hy ried, hwat hurder dat frommes tasette. Hy koe har net kwyt wurde en dreau op 't lêst yn 't swit.","lang":"Fries (Woudfries)","front":"original"},"home":"cab:2"},{"id":"c4","story_id":"CJ026610","role":"member","render":{"description":"Vroeger waren de mensen bang als er eksters bij de deur kwamen. Want dat betekende een dode.","place":"Boelenslaan","prov":"Fr.","year":1967,"code":"SINSAG 0486","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/21410","original":"As der eksters by de doar kommen wienen de minsken froeger bang. Hwant dat bitsjutte in deade.","lang":"Fries (Woudfries)","front":"original"},"home":"1-2"}],"hints":["Kijk naar de nummers in rood potlood.","Drie kaarten vertellen in wezen hetzelfde. De vierde niet.","De kaart over Harkema hoort bij de Witte wieven."],"lock":{"kind":"card_to_cabinet","card":"c3","cabinet":2},"on_success":{"trail_note":0,"unlock_cabinet":2,"stack":["c1","c2","c4"]}},{"id":"1-3","type":"R1","difficulty":1.1391,"rank":0.4477,"note":"De klok staat stil. Deze drie weten hoe laat het is.","cards":[{"id":"c1","story_id":"CJ004302","role":"omen","render":{"description":"In het gezin van de vertelster hadden ze het timmeren aan de Malmoune van tevoren gehoord (de Malmoune was een vierkant huis voor vier a-sociale gezinnen; het werd een paar jaar geleden afgebroken). \nOok hoorden zij van tevoren het zagen en gooien met balken van het huis waar Sjoerd Stienstra in kwam te wonen.","place":"Harkema","prov":"Fr.","year":1966,"code":"SINSAG 0487","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/16068","original":"Wy ha fan tofoaren it timmerjen heard oan 'e Malmoune. (de malmoune wie in fjouwerkant hûs foar fjouwer a-soasiale gesinnen; in pear jier lyn waerd dat hûs ôfbrutsen)\nEk hearden wy fantofoaren it saegjen en 't smiten mei balken fan it hûs dêr't Sjoerd Stienstra, hjir oer de wei, yn kom te wenjen.","lang":"Fries (Woudfries)","front":"description"},"home":"1-3"},{"id":"c2","story_id":"Voda_022_16","role":"omen","render":{"description":"Een geestelijke zag zijn eigen begrafenis. Vier mannen met een baar bleven de hele nacht achter hem lopen. Op dezelfde weg stierf hij later.","place":"Eindhoven","prov":"N.-Br.","year":1977,"code":"SINSAG 0481","initials":"H.E.","url":"https://www.verhalenbank.nl/items/show/129749","original":"Een geestelijke uit Oirschot zag eens zijn eigen begrafenis. Op een nacht ging hij van Oirschot naar Best. Daar hoorde hij achter zich iemand lopen. Toen ie omkeek, zag ie vier mannen die een baar droegen. Hij wilde wachten, maar toen hie stil bleef staan, bleven ook de dragers stilstaan. En als ie verder ging, gingen ook de dragers verder. Zo bleven deze vier mannen met de baar de gehele nacht achter de geestelijke lopen. Die was blij dat ie eindelijk in Best aankwam, waar hij van de schrik kon bekomen. Enige tijd later moest de geestelijke weer naar Best. Daar stierf hij plotseling. Toen droeg men het lijk van de geestelijke over dezelfde weg die hij gelopen had toen de dragers met de baar hem volgden.","lang":"Standaardnederlands","front":"description"},"home":"1-3"},{"id":"c3","story_id":"CJ104404","role":"omen","render":{"description":"De avond voordat IJe vier agenten doodschoot, kleurde de lucht al rood, als voorbode voor het bloed.","place":"Opende","prov":"Gr.","year":1973,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/37442","original":"De jouns fan tofoaren foardat de fjouwer plysjes troch IJe Wykstra fan Greategast deasketten waerden wie de loft alhiel read. Dit hat in foarboade west fan it bloedbad.","lang":"Fries (Woudfries)","front":"description"},"home":"1-3"}],"hints":["Lees ze nog eens. Ze tellen alle drie iets.","Drie keer hetzelfde getal. Zo laat is het.","4 uur. Zet de klok."],"lock":{"kind":"clock_hour","hour":4},"on_success":{"chime":4,"digit":{"value":4,"card":"c1"},"stack":["c1","c2","c3"]}}]},{"id":2,"label":"Witte wieven","digit":2,"drawers":[{"id":"2-1","type":"P4","difficulty":1.6648,"rank":0.5345,"note":"Doorgescheurd. De rest ligt in de doos op tafel.","cards":[{"id":"c1","story_id":"YPFOE070a","role":"top","render":{"description":"Op een kruispunt vlak bij Jistrum spookte het 's nachts. Een van Durk Jaringa's zonen kwam 's avonds na een feestje bij","place":"Burgum","prov":"Fr.","year":1972,"code":"SINSAG 0310","initials":"Y.P.","url":"https://www.verhalenbank.nl/items/show/12146","half":"top"},"home":"2-1"},{"id":"c2","story_id":"ZEEUW054","role":"distractor","render":{"description":"Daar waren 3 koffers met op een 'n hond, op de 2e 'n leeuw met de sleutel van de 3e in zijn bek, die de man moet pakken. Hij durft 't niet en de vrouw neemt afscheid voor 100 jaar.","half":"bottom","code":"SINSAG 0301"},"home":"2-1"},{"id":"c3","story_id":"KEUNING001109","role":"distractor","render":{"description":"met gevlochten manen staat, merkt dat om middernacht paard lawaai maakt en ziet bij het maken van licht een vrouw op het paard.","half":"bottom","code":"SINSAG 0310F"},"home":"2-1"},{"id":"c4","story_id":"YPFOE070a","role":"bottom","render":{"description":"dat kruispunt langs en zag een witte gestalte vlak voor zich heen zweven. Hals over kop rende hij terug naar Jistrum. Een paar anderen hebben hem later langs het kruispunt naar huis gebracht, maar van de gestalte was niets meer te zien.","half":"bottom","code":"SINSAG 0310"},"home":"2-1"},{"id":"c5","story_id":"CJ051004","role":"distractor","render":{"description":"Even plotseling als de vrouw en het paard verschenen zijn, verdwijnen ze weer. De man spoedt zich doodsbenauwd naar huis.","half":"bottom","code":"SINSAG 0310"},"home":"2-1"},{"id":"c6","story_id":"VODA_045_12","role":"distractor","render":{"description":"Sommigen hebben haar ook gezien. Je moest echter niet te dichtbij komen, want dan trok ze je in het water.","half":"bottom","code":"SINSAG 0310"},"home":"2-1"},{"id":"c7","story_id":"ZEEUW056","role":"distractor","render":{"description":"De man ziet dat de hond de duivel is, laat zich weer naar boven brengen, waarna hij wordt vervloekt. Hij komt ziek thuis, en blijft lang ziek. Zijn hele leven blijft hij arm.","half":"bottom","code":"SINSAG 0301"},"home":"2-1"},{"id":"c8","story_id":"CJ001413","role":"distractor","render":{"description":"Hij heeft zijn tante vermoord om haar geld en sinds die tijd spookt het er. Dit alles gebeurt dichtbij de plek waar het huis van sterke Hearke heeft gestaan.","half":"bottom","code":"SINSAG 0311"},"home":"2-1"},{"id":"c9","story_id":"ZEEUW053","role":"distractor","render":{"description":"De geest neemt hem mee door gangen, deuren en zalen, tot ze komen bij 5 kisten, waarop een grote zwarte hond zit, die hem de adem in de keel doet stokken. Hij is niet meer in staat te spreken en de geest neemt voor 100 jaar afscheid en de man staat weer op de weg, waar hij werd aangesproken, en sleept zich huiswaarts en is 2 dagen later dood. Iemand hoorde van zijn avontuur, ging het ook wagen, zag om middernacht een licht voor zich uit dansen, kreeg de schrik en vluchtte weg.","half":"bottom","code":"SINSAG 0301"},"home":"2-1"},{"id":"c10","story_id":"YPFOE088","role":"distractor","render":{"description":"Hij is dat op een gegeven ogenblik beu en wil zijn broer eens goed wakker maken. Daarbij raakt hij hem aan de slaap waarop deze sterft. De familie verhuist omdat ze het niet langer kunnen bolwerken. De lindeboom is blijven bloeien. De vermoorde jongen spookt nog steeds in de buurt rond.","half":"bottom","code":"SINSAG 0311"},"home":"2-1"},{"id":"c11","story_id":"KEMP314","role":"distractor","render":{"description":"Het was lelijk met hem afgelopen als het een andere dag was geweest. De juffrouw geeft hem de mogelijkheid om haar geldkisten op te graven: die hij kan verdelen tussen hemzelf, de armen en de kerk. De volgende dinsdag gaat Drikus met zijn zwager Hannes de schat opgraven. Maar als Hannes zegt: 'kijk, daar zit de heks', zinken de kisten dieper dan ooit.","half":"bottom","code":"SINSAG 0301"},"home":"2-1"},{"id":"c12","story_id":"CBOEK305","role":"distractor","render":{"description":"Als iemand haar rust verstoort, draait ze hem de nek om. Een sterke man gaat 's nachts naar het kasteel waar ze rondspookt en verdelgt haar voorgoed.","half":"bottom","code":"SINSAG 0301"},"home":"2-1"},{"id":"c13","story_id":"TINNEV065","role":"distractor","render":{"description":"Het groepje begint te rennen. Als ze uitgerend zijn vertelt de eerste man dat hij een 'grijze juffer' had gezien.","half":"bottom","code":"SINSAG 0310F"},"home":"2-1"}],"hints":["Lees het bovenste stuk tot het laatste woord. Wat wordt er al genoemd?","Het bovenste stuk breekt midden in een zin af. Het onderste maakt hem af.","Het nummer is SINSAG 0310. Er zijn er drie met dat nummer in de doos."],"lock":{"kind":"card_match","top_card":"c1","bottom_card":"c4"},"on_success":{"fuse":["c1","c4"],"stack":["c1","c4"]},"found_card":{"card":"c4"}},{"id":"2-2","type":"P3","difficulty":1.1405,"rank":0.5773,"note":"Eén hoort hier niet. Terug naar zijn eigen kast.","cards":[{"id":"c1","story_id":"BROUWERS001303","role":"member","render":{"description":"Zien van in het wit geklede vrouw zonder hoofd.","place":"Oud-Valkenburg","prov":"L.","year":1962,"code":null,"initials":"E.H.B.","url":"https://www.verhalenbank.nl/items/show/131805","original":"Van stropers, -----\nEen zekere S. is hier geweest --- een zekere Joep S. die deed niks anders dan stropen.\nDie heb ik eens horen vertellen dat hij hier achter in het veld, in \"der Maord Gieëlender\" (in 't Moord-Gerendal B [Brouwers]) een vrouw ---- een vrouw recht voor hem uit zag lopen ---- Zonder hoofd, ---- Zonder hoofd. En dat mens liep, hebt U niet gezien.\nJa, of zoiets nu waar is en of zo'n man dat nu maar fantaseert, dat weet ik niet, maar hij vertelde het voor echt.\n ------------\nplaats van handeling: Oud-Valkenburg \n\nvraag opn. : hoe was die vrouw gekleed?\nantw. vert. : zij droeg een lang wit kleed en liep op blote voeten. Maar ze \n zweefde meer als dat ze liep. Zo \n vertelde Joep.","lang":"Standaardnederlands","front":"original","uncatalogued":true},"home":"2-2"},{"id":"c2","story_id":"BIJLSMA007508","role":"intruder","render":{"description":"'s Nachts rondlopen van iemand met doodskop en gloeiende ogen en op handen voeten.","place":"Burgum","prov":"Fr.","year":1966,"code":null,"initials":"T.B.","url":"https://www.verhalenbank.nl/items/show/130658","original":"By de Burgemer tsjerke ware nachts in minske op hannen en fuotten om. Hy hie in deadsholle mei eagen as fjûr.","lang":"Fries","front":"original","uncatalogued":true},"home":"cab:4"},{"id":"c3","story_id":"LINSSEN007503","role":"member","render":{"description":"'s Nachts rondzwerven van vrouw zonder kop.","place":"Leveroy","prov":"L.","year":1964,"code":null,"initials":"G.H.L.","url":"https://www.verhalenbank.nl/items/show/208804","original":"Vrouw zonder kop. In de buurt van deze boerderij zwierf 's nachts een vrouw rond:\"de vrouw zonder kop\". Iedereen had schrik daarvoor en 's avonds waagde zich niemand in deze omgeving.","lang":"Standaardnederlands","front":"original","uncatalogued":true},"home":"2-2"},{"id":"c4","story_id":"EGGEN001705","role":"member","render":{"description":"Ontmoeten van door de lucht zwevende witte vrouw.","place":"Berg","prov":"L.","year":1970,"code":null,"initials":"C.E.","url":"https://www.verhalenbank.nl/items/show/207880","original":"Onderwerp : wit wijf.\nTijd : einde 19de eeuw\nPlaats : Berg.\n\nIch weit noch, tot in daen tiēd mèr 'n paar hoezer in Berg sjtonge. En dao op Bemele aan, al gaar gein.\nOppenen aovend, heldere maon, gein mis of gèt, kaom 'n oud vruike nao hoēs, in Berg.\nMèh zie waor kaom aan 't begin van de grwoatstraot (grote straat), dao huërt zie geroēsj in de buim langs de weeg. Dao waor geine wind, en toch roēsjden 't. Zie kraog al gèt angs, en wol vlot wiejer loupe, pes aan de hoezer.\nMèh zie haet nog kaom eine sjtap gezat, dao kump 'n wit wiēf aangezwaef door de loch, zwoa grwoat wie 'ne wollek. \nZie ging rech-op van den angs.\nDoe die versjiening euver waor, leep dat auw minsjke wat 't loupe kòs, nao 't iërsjte hoēs.\nEn van dao haet me hör nao hoēs gebrach.","lang":"Limburgs","front":"original","uncatalogued":true},"home":"2-2"}],"hints":["Drie kaarten vertellen in wezen hetzelfde. De vierde niet.","De vierde gaat over een spook.","De kaart over Burgum hoort bij de Spoken."],"lock":{"kind":"card_to_cabinet","card":"c2","cabinet":4},"on_success":{"trail_note":1,"unlock_cabinet":4,"stack":["c1","c3","c4"]}},{"id":"2-3","type":"R2","difficulty":1.0365,"rank":0.4746,"note":"Er staat iets op het raam. Niet afvegen.","cards":[{"id":"c1","story_id":"LYST283","role":"card","render":{"description":"Een dominee moet 's avonds laat door een donker bos terug naar huis lopen. Hij heeft een angstig voorgevoel dat hem iets zal overkomen. En inderdaad, een wit wief vertoont zich aan hem. De dominee zegt tegen de gedaante dat het mag blijven als het door God gestuurt is, maar dat het moet weggaan als het door de duivel gezonden is. De verschijning verdwijnt onmiddellijk.","place":"Ede","prov":"Gld.","year":1937,"code":"SINSAG 0310","initials":"L.C.S.","url":"https://www.verhalenbank.nl/items/show/13627","original":"Witte Wieven\nDominee Detmar, te Ede, kwam laat terug van het bezoek bij een ouderling en moest de Witte Wieven bij Kernhem passeren. Hij voelde zich ongerust, er zou hem iets gebeuren. Toch ging hij. Op het Hooge Dennenboschje verscheen hem een witte juffer. Dominee zei: \"Ben je van God, dan staat, ben je van de duivel, dan gaat.\" En de gedaante verdween.","lang":"Standaardnederlands","front":"description"},"home":"2-3"},{"id":"c2","story_id":"KEUNING007301","role":"card","render":{"description":"Zien van in het wit geklede vrouw die over sloot stapt, voor paard oversteekt en verder loopt.","place":"Augustinusga","prov":"Fr.","year":1962,"code":"SINSAG 0310F","initials":"S.K.","url":"https://www.verhalenbank.nl/items/show/131331","original":"Pake en omke rieden mei de wein de Achterwei efter de bosk lâns. Doe seach pake in frou oer it lân kommen. Hja wie hielendal yn it wyt. \"Sjoch,\" sei pake tsjin omke. Mar omke seach neat. Pake seach, hoe de frou samar oer de sleat stapte, foar it hynder lâns oer de gong en oer it lân oan de oare kant roun.","lang":"Fries","front":"description"},"home":"2-3"},{"id":"c3","story_id":"CJ124006","role":"card","render":{"description":"Op een spookplaats dansen 's nachts witte wieven.","place":"Mûnein","prov":"Fr.","year":1979,"code":"SINSAG 0310","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/32288","original":"Oan 'e dyk to Readtsjerk spûken wite wiven, nei't se seinen. Dy dounsen dêr nachts om.","lang":"Fries (Woudfries)","front":"description"},"home":"2-3"},{"id":"c4","story_id":"KOOIJMAN2452","role":"card","render":{"description":"Je kon een witte dame zien zweven bij het Kleine Weeltje.","place":"De Moer","prov":"N.-Br.","year":1963,"code":"SINSAG 0310","initials":"H.K.","url":"https://www.verhalenbank.nl/items/show/127820","original":"Vroeger was er bij ons het Kleine Weeltje. Het bestaat nog, het ligt tussen Klundert en Zevenbergen. Als 't nou goed weer was geweest dan zag je daar op een zomeravond volgens de verhalen een witte dame zweven. Vooral als 't mistig was, als er dauw was. 't Was een wezen met vleugels, ze had helderwitte kleding en een krans om het hoofd. 't Was een glinsterend wezen. Op zomeravonden, dan speelde en vloog ze boven die weel. 't Hoefde niet donker te zijn. En ineens was ze dan weer verdwenen.","lang":"Standaardnederlands","front":"description"},"home":"2-3"},{"id":"c5","story_id":"LYST277","role":"card","render":{"description":"Een boerenknecht komt langs de Witte Wieve en daagt ze uit. Een van hen achtervolgt hem tot huis. Hij kan net naar binnen vluchten. Ze gooit echter een knuppel naar de deur, waardoor er een stuk van de stiepel breekt.","place":"Almelo","prov":"Ov.","year":1937,"code":"SINSAG 0161","initials":"A.G.K.","url":"https://www.verhalenbank.nl/items/show/13621","original":"In Almelo gaat onder oudere personen (70 - 80 jaar) het verhaal rond van de Witte Wieve van de Alberger hei. Zij vertellen het volgende:\nAlbergen is een gehucht op zes kilometer afstand van Almelo aan de weg naar Ootmarsum. De Alberger hei strekte zich vroeger uit tussen dit gehucht en de bezittingen van Huize Almelo. Men dacht dat ze woonden in een grote tumulus, die zich in 't midden bevond. Men zegt dan, dat als voorzorgsmaatregel, dat de witte wieve niet in huis zouden komen, de boerenbehuizingen een kruis in de middenpost van de baanderdeur, \"stiepel\" genaamd, hadden aangebracht op ongeveer een meter. …","lang":"Standaardnederlands; Twents","front":"description"},"home":"2-3"},{"id":"c6","story_id":"CJ057303","role":"sill","render":{"description":"Meerdere mensen hebben door het bos twee witte wijven gezien.","place":"Opende","prov":"Gr.","year":1969,"code":"SINSAG 0310","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/25852","stain":"twee"},"home":"2-3"}],"hints":["Lees het van achteren naar voren.","Het begint met een O.","Opende. Leg die kaart op de vensterbank."],"lock":{"kind":"card_to_object","card":"c6","object":"window","text":"Opende"},"on_success":{"digit":{"value":2,"card":"c6","word":"twee","stained":"c6"},"stack":["c1","c2","c3","c4","c5","c6"]}}]},{"id":3,"label":"Weerwolven","digit":3,"drawers":[{"id":"3-1","type":"P6","difficulty":3.3045,"rank":0.8837,"note":"Elk verhaal één getal. In deze volgorde.","cards":[{"id":"c1","story_id":"YPFOE114a","role":"clip1","render":{"description":"Eén verhaal over weerwolven gaat als volgt; een man en een vrouw komen in een rijtuig aanrijden. De man roept meerdere malen naar zijn vrouw dat hij haar eruit moet laten. Hij waarschuwt haar dat er anders wat vreselijks met haar zal gebeuren. De vrouw wordt bang en laat hem uit het rijtuig. Ze rijdt snel door maar de man vliegt haar achterna. Ze weet nog maar net te ontsnappen.","place":"Leeuwarden","prov":"Fr.","year":1972,"code":null,"initials":"Y.P.","url":"https://www.verhalenbank.nl/items/show/12467","original":"Wjerwolven\nSa haw ik yn myn jonge jierren wol ris heard fan wat se dan neamden de wjerwolf. En dat skynde dan noch al ris foar te kommen. Ien ferhaal wisten se my foar wier te fertellen, dat is bard yn'e Hommerts.\nDêr kaam in pearke oanriden op in krompanelen seas. Se rieden op nei hûs en op in stuit sei de feint tsjin 'e faam: 'Do moatst der my út litte! Do moatst der my út litte!' 'Wêrom dat?''Oars bart der wat dat dy ivich spite sil!'\nNo, en hy hâlde sa oan, dat sy waard bang fan him—ik tink, dat sy mende—en se hâlde it hynder yn en liet him fan 'e seas ôf. Doe ried se wer fuort en nei't it ferhaal dan giet, fleach er har efternei en koe se mar justjes úntkomme.","lang":"Fries","front":"description"},"home":"3-1"},{"id":"c2","story_id":"GENDT089","role":"clip2","render":{"description":"Een groepje kaarters heeft het idee dat één van hen een weerwolf is. Als deze man weg wil gaan 's avonds houden ze hem vast en laten ze hem niet gaan. Als zijn wolvenvel door de schoorsteen komt valt het in het vuur en verbrandt. Nu is de man bevrijd.","place":"Gendt","prov":"Gld.","year":1965,"code":"SINSAG 0824","initials":"M.H.D.","url":"https://www.verhalenbank.nl/items/show/49725","original":"Mien voader het wel es verteld, dat ze vroeger duk same gienge koarte, erges bé’j iemes ien de buurt. D’r waster één ien de ploeg, wor ze van dochte, dattie duk gieng werwolve. Op ’n keer ware ze weer on ’t koarte. Op zekere tied wou die kjel weg. Mar d’aander wouwe ’m nie loate goan. Ze hemmen ’m vasgegrope en ’m nie losgeloate, al gieng ie nog zo d’rop. Opens kwam er ’n wolvevel dör de schorsten valle. Da verbraandde. En toe zeitie: “Nou ziet ’k teraf! As ik los gekomme was en ik had ’t vel kunne kriege, dan ha’k hier alles kort en klein geslage”.","lang":"Gendts (Achterhoeks)","front":"description"},"home":"3-1"},{"id":"c3","story_id":"CJ085401","role":"clip3","render":{"description":"Een van zeven broers is een weerwolf. Als hij weer een kuur heeft, moet men hem een oud schort of iets toewerpen. Dat verscheurt hij dan. Als men iemand met de draden uit zijn mond ziet, kan men ervan opaan dat dat een weerwolf is.","place":"Rottevalle","prov":"Fr.","year":1971,"code":"TM 3107","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/33002","original":"In wearwolf is in minske, dy forropt de boel. 't Is ien fan sawn jonges (7 bruorren). As er wer sa'n kuer krijt, dat er hwat forskuorre mat, mat men him in âld skelk of sahwathinne tasmite. Us mem sei, dan gebeurde 't wol dat him even letter de triedden ta de mûle úthongen.\nAs men sa'n ien seach, dy't triedden ta de mûle út hie, koe men der fan op oan dat it in wearwolf wie. Dêr koe men se oan herkenne.","lang":"Fries (Woudfries)","front":"description"},"home":"3-1"},{"id":"c4","story_id":"ZEEUW180","role":"inside","render":{"description":"Weerwolven wisten hun uur, dat ze weg moesten; als ze dan bij hun meisje terugkwamen, hadden ze rode draden van een sjaal tussen de tanden zitten.","place":"Hulst","prov":"Zl.","year":1923,"code":"SINSAG 0823","initials":"P.A.E.","url":"https://www.verhalenbank.nl/items/show/35896","original":"Weerwolven.\n\nIk 'èn mijn moeder nie lank gekend. Z' is gestorven in 't jaar da'nk mijn êêste kommienie gedaan èn, maar ik weet nog goed de' ze altijd vertelde-n van Ossaart in van wjèrwolven, in wij stongen d'r ammaal rond, in luisteren, da' begrijpte.\nDan vertelde-n ze van die jongers, da' waren wjèrwolven, in die wisten ulder uur, in dan mochten ze weg. An'ze dan bij ulder meid waren Sondaasavens, dan mochten z' in eens weg in dan gebeurde-n 't an 'ze trugkwamen dan de rôôie draaien van 'ne sjal tussen ulder tanden zaten.","lang":"Zeeuws","front":"original","note":"Deze bewaar ik apart."},"home":"3-1"}],"hints":["Elk verhaal telt.","Het eerste getal is 1.","1 — 1 — 7."],"lock":{"kind":"number3","salt":"beb94d96b42a8c9d","accepted_hashes":["3744f6259f04196671909050eac3f1b0953d2d9a48fbd5f699dd4bd2defd29f5"]},"on_success":{"stack":["c1","c2","c3","c4"]},"found_card":{"card":"c3"}},{"id":"3-2","type":"P3","difficulty":1.2475,"rank":0.7798,"note":"Eén hoort hier niet. Terug naar zijn eigen kast.","cards":[{"id":"c1","story_id":"CJ015102","role":"intruder","render":{"description":"Een ongeduldige, ruwe boer wil voor de avond een groot stuk land omgeploegd hebben. De knecht vertikt het en zegt de boer dat hij maar naar de duivel kan lopen met zijn voorstel. De boer vat dit letterlijk op en schakelt de hulp van de duivel in. De volgende morgen is het land omgeploegd. Zijn dwepen met de duivel is de boer duur komen te staan: op zijn sterfbed werd hij door de duivel opgehaald.","place":"Hurdegaryp","prov":"Fr.","year":1967,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/19770","original":"Der wie in boer, dat wie in forwoesteling. Hy wie altyd gleonhastich en net in arbeider dy't it by him úthâlde koe. Op in kear hied er wer in arbeider, doe moest der ploege wurde. It wie al let yn 'e joun en it wie ûnmooglik dy greate hoeke lân foar de nacht noch to ploeijen. Dat de arbeider sei tsjin 'e boer: \"Freegje de duvel, dat dy it docht.\" De boer sei: \"Dat dog ik\" en hy die it ek.\nDe oare moarns wie it stik lân ploege.\nMar hy hat it sûr bikeapje matten. Doe't er op syn stjerbêd lei, hat de duvel him helle.","lang":"Fries (Woudfries)","front":"original","uncatalogued":true},"home":"cab:5"},{"id":"c2","story_id":"VVUNL049","role":"member","render":{"description":"Elke avond na het eten gaat Sjang weg en komt pas heel laat terug. Op een keer volgen ze hem en zien hem iets uit een boom halen en even later was hij een weerwolf. De pastoor wordt gehaald en Sjang moet zijn spullen tevoorschijn halen. Er kwam een schapevacht en een rood stokje met rood lint uit; die worden in de oven verbrand, terwijl drie man Sjang in bedwang houden. Als alles verkoold is, zegt hij verlost te zijn.","place":"Kessel","prov":"L.","year":1952,"code":null,"initials":"J.N.","url":"https://www.verhalenbank.nl/items/show/35588","original":"De geplaagde herder \n\n't Gebeurde op 'Gravenhof' te Kessel, tussen 1860 en '70. Sjang van de Maas uit Neer was hier scheper; een onnozele, rustige kerel, die niemand kwaad deed, en elke dag zijn schapen hoedde. Maar na een tijdje maakten de boer en de boerin zich over hem ongerust. Elke avond na het eten verdween Sjang plotseling en keerde pas heel laat in de nacht weer huiswaarts. Dit werd zo verdacht dat men op een keer de knaap stilletjes achtervolgde... Men zag toen dat hij tot de holle boom liep, even voorbij het Annakapelletje; daar nam hij iets uit. Na enkele ogenblikken veranderde hij van gedaante, en stoof als schrikaanjagende weerwolf met een geweldige vaart weg. . . …","lang":"Standaardnederlands","front":"original","uncatalogued":true},"home":"3-2"},{"id":"c3","story_id":"ENGELS000115","role":"member","render":{"description":"Weerwolf bespringt 's avonds mensen; als helper bij werk; verandering in weerwolf door aantrekken verborgen jas, na verbranden jas bevrijding.","place":"Helden","prov":"L.","year":1962,"code":null,"initials":"G.G.E.","url":"https://www.verhalenbank.nl/items/show/57969","original":"Weerwolven:\nMannen, die wat laat op de baan waren, werden, vooral in donkere, stormachtige nachten soms besprongen door de weerwolf. Dit spookdier met gloeiende ogen sprong hen op de rug, en klemde zich met de voorpoten om hun nek. Ze bleven zich als een zware last aan de verschrikte man klemmen totdat hij ergens een huis bereikte. In de Broekbeemd, tussen Onder-Eijndt en Zandberg, stond ergens een holle eiken knot of poesjt. Er was een man, die als weerwolf bekend werd. Hij had een aparte jas; als hij deze aantrok werd hij weerwolf. Na zijn nachtelijke tochten verborg hij deze jas in die holle “poesjt”. Zijn buurlui ontdekten dit, en staken de “poesjt” met de jas in brand. …","lang":"Standaardnederlands; Limburgs","front":"original","uncatalogued":true},"home":"3-2"},{"id":"c4","story_id":"KEMP298","role":"member","render":{"description":"Een pachter komt erachter dat een kleine scheper op zijn boerderij vermoedelijk een weerwolf is. Hij stuurt hem weg voor een dag en hij en zijn knechten ontdekken in een holle wilg een wolvenvel. Ze steken het thuis in brand. De scheper keert vervolgens in razend tempo terug en wil zijn vel teruggrijpen. Als dat niet lukt, vlucht de scheper naar de holle boom en is nooit meer teruggezien.","place":"Broek","prov":"L.","year":1925,"code":null,"initials":"I.S.","url":"https://www.verhalenbank.nl/items/show/43423","original":"Het weerwolfsvel verbrand\n\nBij de pachter van de boerderij bij het kasteel Geusselt onder Amby diende eens een scheper, een klein manneke, dat de naam had een weerwolf te zijn. 's Nachts was hij nooit in bed te vinden, maar 's morgens lag hij er weer in. De knechts van de hoeve hadden dat al dikwijls bemerkt.\nWijl dit zo opvallend was, werd zijn doen en laten gedurig bespied en zo bemerkte men dan ook dat hij, wanneer hij 's avonds uit zijn bed kroop, naar een weide ging, waar heel eenzaam een grote holle wilg stond. Daar verdween hij iedere keer in.\nOm het fijne van de zaak te achterhalen stuurde de pachter hem op zekere namiddag naar een dorp, dat meer dan drie uur van de hoeve lag, om daar koeien te kopen. …","lang":"Standaardnederlands","front":"original","uncatalogued":true},"home":"3-2"}],"hints":["Drie kaarten vertellen in wezen hetzelfde. De vierde niet.","De vierde gaat over de duivel.","De kaart over Hurdegaryp hoort bij de duivel."],"lock":{"kind":"card_to_cabinet","card":"c1","cabinet":5},"on_success":{"trail_note":3,"unlock_cabinet":5,"stack":["c2","c3","c4"]}},{"id":"3-3","type":"R3","difficulty":1.1088,"rank":0.8205,"note":"Als er geklopt wordt: tel. Die kaart onder de deur.","cards":[{"id":"c1","story_id":"LYST008","role":"card","render":{"description":"Een boerenknecht haalt iedere nacht precies om twaalf uur een hoepeltje uit de lindeboom. Hij hangt de hoepel om zijn nek en verandert in een weerwolf. Hij loopt een tijdje rond en verscheurt alles wat er in zijn buurt komt. Hierna wordt hij weer gewoon mens. De boer vindt zijn gedrag maar vreemd en vraagt raad aan de pastoor. De pastoor heeft door dat de boerenknecht een weerwolf is, en adviseert de boer om de knecht een boodschap te laten doen waarbij hij nooit om middernacht weer thuis kan zijn. Op de afgesproken nacht haalt de pastoor om middernacht de hoepel uit de boom. De knecht staat onder die boom en ziet alles. Hij vlucht en komt nooit meer terug.","place":"Erp","prov":"N.-Br.","year":1953,"code":"SINSAG 0803","initials":"F.W.J.S.","url":"https://www.verhalenbank.nl/items/show/13222","original":"De Weerwolf\nEen boerenknecht kroop 's nachts klokslag 12 uur in de lindenboom voor de boerderij. Boven in de boom hing voor gewone mensen onzichtbaar een hoepeltje. Dat hing de knecht om zijn hals. Als ie uit de boom geklauterd was, liep ie in de gedaante van een hond weg en verscheurde alles wat hem in de weg kwam. Als ie een tijd zo rondgelopen had, was ie weer gewoon mens. Na een tijd was het de boer, bij wie de weerwolf in dienst was, opgevallen, dat zijn knecht nacht op nacht weg was. Hij ging naar de pastoor en die had het zaakje meteen door. …","lang":"Standaardnederlands","front":"description"},"home":"3-3"},{"id":"c2","story_id":"LYST189","role":"door","render":{"description":"Drie mensen vertellen dat zij 's avonds laat een grote hond met vurige ogen zijn tegengekomen, die bij hen op de rug sprong. Pas bij de grens van het stuk land sprong hij eraf en verdween. De hond verdween bij een boerderij die al als \"niet pluis\" bekend stond, omdat de knecht van die boerderij vertelde dat de koeien enkele malen om klokslag middernacht opsprongen terwijl de staldeuren vanzelf opensprongen.","place":"Puiflijk","prov":"Gld.","year":1957,"code":"SINSAG 0801","initials":"C.v.d.P.","url":"https://www.verhalenbank.nl/items/show/13453","original":"Spookdieren\nMij is eens door drie verschillende personen op zeer verschillende tijden meegedeeld dat op de Waaldijk tussen Boven-Leeuwen en Druten 's avonds in pikdonker plotseling een abnormale grote hond, die plotseling verscheen, hen zwijgend met vurige ogen volgde en even plots aan de grens van Druten verdween. Beide personen waren niet bijgelovig maar hadden van angst 't zweet op de rug staan van angst, temeer daar de hond verdween bij een boerderij waar 't niet \"pluis\" scheen te zijn. Een knecht op deze boerderij vertelde mij eens hoe verscheidene malen 's nachts de koeien om klokslag 12 uur opsprongen en staldeuren openvlogen zonder 'n aanwijsbare oorzaak. …","lang":"Standaardnederlands","front":"description"},"home":"3-3"},{"id":"c3","story_id":"TINNEV042","role":"card","render":{"description":"Twee mannen zoeken grasstengels om te snijden. Als ze er geen vinden gaan ze maar naar huis. Wanneer ze uit elkaar zijn gegaan ziet de ene man ineens een grote wolf op zijn pad. De volgende morgen vraagt de andere man aan hem of hij de wolf heeft gezien.","place":"Didam","prov":"Gld.","year":1944,"code":"SINSAG 0823","initials":"A.T.","url":"https://www.verhalenbank.nl/items/show/22388","original":"29.\nPeter ging op een kier met Dorus mieskes sni'je. Mao zi'j konne de gin vinne en wolle daorum weer op huus aan. De weg liep deur een buske. Dorus vroeg aan Peter offe um nao huus sol brenge. \"Loop nao da galg\", antwore Peter en kroap onder de scheibeum nève de weg hèèr.\n\"Hi'j is ter\", riep Dorus um nao. Ienéns stong d'r een grote wolf op de bosweg. Hi'j wol niet op zied gaon. Daorum drèèje Peter de met een flinken boag umhen. Toe e is umkek zag e niks meer. Umdat Peter geld neudig had ginge de 's marges weer op uut um smele te zuke. Ien Kilder was Dorus al met een groten trop aan 't sni'je. Toe hi'j Peter zag riep tem toe: \"Wasse d'r now, of niet?\".","lang":"Liemers","front":"description"},"home":"3-3"},{"id":"c4","story_id":"CJ071510","role":"card","render":{"description":"Een weerwolf is een jongeman die op een paard rijdt. Hij plaagt het paard net zoals een nachtmerrie een mens plaagt. Het is een van zeven broers.","place":"Rohel","prov":"Fr.","year":1969,"code":"TM 3107","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/28067","original":"In wjerwolf is in manspersoan, - meastal in jongkeardel -, dy't op in hynder rydt. Hy pleaget dat hynder, krekt as in nachtmerje de minsken. 't Is ien fan sawn bruorren. Ik ha wol ien kend, dy wenne yn Warffum.","lang":"Fries (Woudfries)","front":"description"},"home":"3-3"},{"id":"c5","story_id":"CJ071310","role":"card","render":{"description":"Een van acht zoons was een weerwolf. Een weerwolf kon zich nooit vol eten, hij had altijd nog honger.","place":"Houtigehage","prov":"Fr.","year":1969,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/28045","original":"As der acht jonges wienen, dy't op elkoar folgen yn in húshâlding, dan wie ien fan dy acht in wjerwolf. Dat wie ien dy't noait sêd koe, dy't neat fan ûnpas kom.","lang":"Fries (Woudfries)","front":"description"},"home":"3-3"}],"hints":["Wacht op het kloppen. Tel het.","Een oneven getal.","3 keer. Die kaart."],"lock":{"kind":"card_to_object","card":"c2","object":"door","n":3},"on_success":{"digit":{"value":3,"card":"c1"},"stack":["c1","c3","c4","c5"]}}]},{"id":4,"label":"Spoken","digit":6,"drawers":[{"id":"4-1","type":"P5","difficulty":0.696,"rank":0.5,"note":"De vertellers spreken elkaar tegen. Houd de oudste aan.","cards":[{"id":"c1","story_id":"CJ012304","role":"variant","render":{"description":"Een man loopt 's nachts tegen een uitzonderlijk lang persoon aan. De man kon niet zien of het een man of een vrouw was, en de persoon reageerde niet op zijn groet.","place":"Boornbergum","prov":"Fr.","year":1966,"code":"SINSAG 0475","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/19313","original":"Us heit is us in kear tsjin ien oanroan op 'e Berchloane hjir yn Drachten. 't Wie yn 'e nacht. Heit woarde bot kjel, mar dy oare hielendal net. It wie ien, dy wie útsûnderlike lang. Heit moest in hiel ein omheech sjen, woed er it gesicht observearje. Heit koe net gewaer wurde of it in man of in frommes wie mar it wie in hiel lang wezen en 't sei neat, doe't heit \"navend\" sei.","lang":"Fries (Woudfries)","front":"description"},"home":"4-1"},{"id":"c2","story_id":"CJ071105","role":"variant","render":{"description":"Een jongeman zag op een avond twee mannen passeren. Zij antwoordden niets op zijn groet en waren opeens verdwenen.","place":"Twijzel","prov":"Fr.","year":1969,"code":"SINSAG 0475","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/28005","original":"In jongfeint tsjinne achter de Falom.\nHy reizge op in joun lâns de Boppe-wei mei de Spûkloane nei Kollumersweach.\nDêr kom er twa man tsjin en it like krekt as hienen dy ien tusken har yn.\nHy moest har passeare en sei: \"Goejoun.\"\nMar sy seinen neat werom en wienen samar ynienen fuort.","lang":"Fries (Woudfries)","front":"description"},"home":"4-1"},{"id":"c3","story_id":"CJ087607","role":"variant","render":{"description":"Een man zag op een vroege ochtend een man in de berm. Op zijn groet antwoordde de vreemdeling niets. Die ging er snel vandoor, de man kon hem helemaal niet meer inhalen. Het leek wel of de vreemdeling zweefde, de man kon ook geen voetsporen van hem vinden.","place":"Drogeham","prov":"Fr.","year":1971,"code":"SINSAG 0475","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/33174","original":"Op in moarn roan ús heit fan 'e Harkema nei 't Wytfean ta. Hy soe nei de boer ta to melken. Underweis soed er syn maet oanhelje. Dy wenne ek yn 'e Harkema en dy arbeide ek by in boer op it Wytfean.\nHeit wie noch net oan dy man ta, doe kom der him ien tomjitte yn 'e berm. Heit sei: Goeije morgen, mar dy oare sei neat werom. Doe sei heit nochris Goeije morgen, mar de oare sei wer neat. Dit is in nuver spul, tocht heit, dêr wol 'k mear fan wite. Heit der achteroan.\nIt mes hie heit ta de bûse út lutsen en dat hâldde er klear. Mar hy koe dy oare net birinne. Dy oare sweefde. Dyselde hie gjin fuotten. Doe't heit sa in ein roan hie, skeat de oare by ien op it hiem en fuort wied er. Heit der achteroan, èk it hiem op. …","lang":"Fries (Woudfries)","front":"description"},"home":"4-1"},{"id":"c4","story_id":null,"role":"summary","render":{"description":"In Friesland werd een tijdstip genoemd: ____. (volgens de oudste opname)","place":null,"year":null,"code":null,"initials":"J.D.","summary":true},"home":"4-1"}],"hints":["Kijk naar de jaartallen.","De oudste is uit 1966.","Op die kaart staat een tijdstip. Welk?"],"lock":{"kind":"word","salt":"beb94d96b42a8c9d","accepted_hashes":["b61f0d5e6c382c3b64ccb00c8bd29656f26ec0a601c12ddc4f4f7e69eba841a5","f23a535c427dbcf97d01f6fd00833163d9b503bfab940744ecf8d6672fb5e102"],"fill":"c4"},"on_success":{"fill_field":{"card":"c4","field":"blank","value":"typed"},"stack":["c1","c2","c3","c4"]},"found_card":{"card":"c3"}},{"id":"4-2","type":"P3","difficulty":1.2288,"rank":0.7393,"note":"Eén hoort hier niet. Terug naar zijn eigen kast.","cards":[{"id":"c1","story_id":"CJ025502","role":"member","render":{"description":"In Westereinde spoken 's nachts altijd twee meisjes.","place":"Kollum","prov":"Fr.","year":1967,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/21287","original":"Yn 'e Westerein, yn in loantsje by 't spoar, roannen yn 'e nacht altyd twa famkes om. Dy spoeken dêr. Dêr doarsten de minsken nachts net lâns.","lang":"Fries (Woudfries)","front":"original","uncatalogued":true},"home":"4-2"},{"id":"c2","story_id":"CJ093617","role":"member","render":{"description":"Mensen zagen vroeger wel eens witte wijven.","place":"Rottevalle","prov":"Fr.","year":1972,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/33731","original":"Yn 'e omkriten fan Rottefalle hâldden froeger wite wiven ta.","lang":"Fries (Woudfries)","front":"original","uncatalogued":true},"home":"4-2"},{"id":"c3","story_id":"CJ057209","role":"member","render":{"description":"Mensen zagen vroeger vaak een meisje in zwart zijden kleding spoken.","place":"Kollumersweach","prov":"Fr.","year":1969,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/25831","original":"Op 'e Mûzewei (= Mûntse-wei) fan Aldwâld nei Feankleaster spoeke in juffer yn 't swart. Dy roan dêr altyd om. Underskate lju ha har dêr sjoen. Hja hie swart-sidene mofkes oan 'e hannen en in swart-sidene jurk hie se oan. Hja gong dêr nei in plaets ta. Dêr stie in plakje mei woartels flak by. Dêr roan se altyd oan ta, dan gong se werom. Guon seinen. hja gong ek wol nei 't slot ta. De minsken hearden de side ritseljen.","lang":"Fries (Woudfries)","front":"original","uncatalogued":true},"home":"4-2"},{"id":"c4","story_id":"HOL001815","role":"intruder","render":{"description":"Weerwolven hebben vel om, laten zich dragen; plaats waar ze te horen zijn.","place":"Lienden","prov":"Gld.","year":1963,"code":null,"initials":"A.R.H.","url":"https://www.verhalenbank.nl/items/show/209954","original":"Weerwolven hadden een vel om. Ze hadden er plezier om bij iemand op de kruiwagen, ook op de rug te springen. Die dit overkwam moest de weerwolf kruien of dragen. En die was zwaar, hoor!\nJuffrouw Van Kalkeren weet nog, hoe haar vader (geb. 1861) altijd blij was geweest, dat hij \"de krump”\"(= de kromming, bocht) van de Groene Straat, waarin hij voor zijn huwelijk woonde, was gepasseerd. In die \"krump\" zaten altijd weerwolven te brommen. (Ik ben na afloop van deze opname door de Groene Straat teruggegaan, terwijl het al donker was en heb geen gebrom gehoord).","lang":"Standaardnederlands","front":"original","uncatalogued":true},"home":"cab:3"}],"hints":["Drie kaarten vertellen in wezen hetzelfde. De vierde niet.","De vierde gaat over een weerwolf.","De kaart over Lienden hoort bij de Weerwolven."],"lock":{"kind":"card_to_cabinet","card":"c4","cabinet":3},"on_success":{"trail_note":2,"unlock_cabinet":3,"stack":["c1","c2","c3"]}},{"id":"4-3","type":"R4","difficulty":1.1885,"rank":0.7083,"note":"Als de machine begint: laten uittikken. Het vervolg zit hierin.","cards":[{"id":"c1","story_id":"CBAK0376","role":"top","render":{"description":"Boer op een boerderij waar het spookt vraagt aan een bedelende oude soldaat of hij 's nachts wil waken.","place":"Uitdam","prov":"N.-H.","year":1903,"code":"SINSAG 0401","initials":"C.B.","url":"https://www.verhalenbank.nl/items/show/9190","half":"top"},"home":"4-3"},{"id":"c2","story_id":"CJ081008","role":"half","render":{"description":"Ze zagen daar langs de kant een reus, die wel twee keer zo groot was als een normaal mens. Een groot kleed wapperde om hem heen, verder stond hij helemaal stil. Het was een spook.","half":"bottom","code":"SINSAG 0475"},"home":"4-3"},{"id":"c3","story_id":"BIJLSMA003301","role":"half","render":{"description":"Na zijn dood hoort zijn weduwe 's avonds hetzelfde geluid dat haar man maakte als hij naar boven ging. Bezoek gaat kijken en hoort kloppen bij een boek. Bij oppakken vallen de papieren uit het boek.","half":"bottom","code":"SINSAG 0401"},"home":"4-3"},{"id":"c4","story_id":"CJ058107","role":"half","render":{"description":"Opeens zagen ze een kerel met een hoed op. Toen hij hen passeerde, was hij opeens verdwenen.","half":"bottom","code":"SINSAG 0475"},"home":"4-3"},{"id":"c5","story_id":"CBAK0513","role":"half","render":{"description":"Het antwoord is dat ze lang op iemand hebben gewacht, dat er geld ligt begraven waarvan hij een derde mag hebben, en de rest gelijkelijk naar de armen en een kerkelijke gemeente moet gaan. Nadat aan het verzoek is voldaan houdt het spoken op.","half":"bottom","code":"SINSAG 0401"},"home":"4-3"},{"id":"c6","story_id":"CJ015103","role":"half","render":{"description":"Als de man en zijn nieuwe bruid in het rijtuig willen stappen, verschijnt plotseling zijn overleden vrouw. Ze wijst hem op zijn belofte en het kersverse echtpaar maakt het huwelijk ongedaan. De geest van de overledene kan past rust vinden als een belofte - voor de dood gedaan - is nagekomen.","half":"bottom","code":"SINSAG 0402"},"home":"4-3"},{"id":"c7","story_id":"CBAK0376","role":"bottom","render":{"description":"Om middernacht komen na veel lawaai zes hoge militairen met sabels binnen die naar de hooiberg gaan. Zij graven daar een gat, halen er een ketel met goudgeld uit, begraven die weer en vertrekken. De bedelaar graaft met hulp van een knecht de ketel op. De volgende nacht waken ze samen, zien de mannen weer komen, die vertrekken en nooit meer terugkomen als ze niets meer vinden. De soldaat blijft op de boerderij. Volgens de verteller is het voorzienigheid geweest dat de soldaat het geld moest hebben.","half":"bottom","code":"SINSAG 0401","stain":"zes"},"home":"4-3"}],"hints":["Lees wat de machine getypt heeft, tot het laatste woord.","Het vervolg noemt ‘boerderij’ opnieuw.","Het nummer is SINSAG 0401. Er zijn er maar drie in de envelop."],"lock":{"kind":"card_match","top_card":"c1","bottom_card":"c7","object":"typewriter"},"on_success":{"fuse":["c1","c7"],"type_line":"Verteller: de vorige assistent.","digit":{"value":6,"card":"c1","word":"zes","stained":"c7"},"stack":["c1","c2","c3","c4","c5","c6","c7"]}}]},{"id":5,"label":"De duivel","digit":null,"drawers":[]}]});
